    pass

class gsl_vector_complex(ctypes.Structure):
    pass

class gsl_eigen_nonsymm_workspace(ctypes.Structure):
    pass

def create_gsl_matrix(matrix):
    rows, cols = len(matrix), len(matrix[0])
    gsl_matrix_ptr = gsl.gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_set(gsl_matrix_ptr, i, j, matrix[i][j])
    return gsl_matrix_ptr

def create_gsl_vector_complex(size):
    gsl_vector_complex_ptr = gsl.gsl_vector_complex_alloc(size)
    return gsl_vector_complex_ptr

def compute_eigenvalues_nonsymm(matrix):
    gsl_matrix_ptr = create_gsl_matrix(matrix)
    size = len(matrix)
    gsl_vector_complex_ptr = create_gsl_vector_complex(size)
    workspace = gsl.gsl_eigen_nonsymm_alloc(size)
    gsl.gsl_eigen_nonsymm(gsl_matrix_ptr, gsl_vector_complex_ptr, workspace)
    return [complex(x.real, x.imag) for x in gsl.gsl_vector_complex_get_values(gsl_vector_complex_ptr)]

