    gsl.gsl_linalg_exponential_ss.argtypes = [
        ctp.POINTER(ctp.c_double), ctp.c_int, ctp.c_int, ctp.c_int
    ]

    gsl_matrix = matrix_to_gsl(matrix)
    rows, cols = gsl_matrix.rows, gsl_matrix.cols

