    result = np.zeros((rows, cols), dtype=np.float64)
    gsl_result = ctp.POINTER(ctp.c_double)(result.ctypes.data)

    status = gsl.gsl_linalg_exponential_ss(
        gsl_result, rows, cols, mode
    )

    if status != 0:
        raise RuntimeError("Error in matrix exponential computation.")

    return gsl_matrix_to_numpy(gsl_matrix)

