def create_histogram2d(nx, ny, xrange, yrange):
    if nx <= 0 or ny <= 0:
        raise ValueError("nx and ny must be positive integers")

    if len(xrange) != nx + 1 or len(yrange) != ny + 1:
        raise ValueError("xrange and yrange must have nx+1 and ny+1 elements")

    if not all(xrange[i] < xrange[i + 1] for i in range(nx)):
        raise ValueError("xrange must be in increasing order")

    if not all(yrange[i] < yrange[i + 1] for i in range(ny)):
        raise ValueError("yrange must be in increasing order")

    gsl.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    xrange_ptr = (ctypes.c_double * len(xrange))(*xrange)
    yrange_ptr = (ctypes.c_double * len(yrange))(*yrange)

    return gsl.gsl_histogram2d_calloc_range(nx, ny, xrange_ptr, yrange_ptr)

